// =================================================================
// MALAFO v3 — guides.js
// Real animal outlines from uploaded images.
// Background removed, outline recolored amber for camera overlay.
// Single photo mode — no front/back/side tabs.
// =================================================================

const ANIMAL_IMGS = {
  horse: "data:image/png;base64,",
  cow: "data:image/png;base64,",
  sheep: "data:image/png;base64,",
  goat: "data:image/png;base64,",
  camel: "data:image/png;base64,",
};

// GUIDES object: each animal has only "side" (single photo mode)
// Renders the real image outline as SVG <image> centered in viewBox
const GUIDES = {};

const _sizes = {
  horse: [201, 300],
  cow:   [201, 300],
  sheep: [201, 300],
  goat:  [201, 300],
  camel: [201, 300],
};

// Build GUIDES entries from images
// viewBox is 300x200, center the animal image
Object.keys(ANIMAL_IMGS).forEach(animal => {
  const [iw, ih] = _sizes[animal] || [201, 300];
  // Scale to fit in ~240x170 area centered in 300x200 viewBox
  const scale = Math.min(240 / iw, 170 / ih);
  const w = Math.round(iw * scale);
  const h = Math.round(ih * scale);
  const x = Math.round((300 - w) / 2);
  const y = Math.round((200 - h) / 2);

  GUIDES[animal] = {
    side: `<image href="${ANIMAL_IMGS[animal]}" x="${x}" y="${y}" width="${w}" height="${h}" opacity="0.75"/>`
  };
});
